278|        throw new Error(`track ${id} source must be generated, jamendo, or recording`);
279|      }
280|      trackSource = source;
281|    }
282|    const credit: { artist?: string; composer?: string; license?: string; attribution?: string } = {};
283|    const pairs = [
284|      ["artist", artist],
285|      ["composer", composer],
286|      ["license", license],
287|      ["attribution", attribution],
288|    ] as const;
289|    for (const [key, value] of pairs) {
