90|// Cosine over buildFeatures output (vector plus weighted intensity and
91|// tempo). Kept as an alternative; it favors peaky scenes.
92|export function cosineSimilarity(scene: SceneSignal, track: Track): number {
93|  const a = buildFeatures(scene);
94|  const b = buildFeatures(track);
95|  let dot = 0;
96|  let na = 0;
97|  let nb = 0;
98|  for (let i = 0; i < a.length; i++) {
99|    const x = a[i] ?? 0;
100|    const y = b[i] ?? 0;
101|    dot += x * y;
102|    na += x * x;
103|    nb += y * y;
104|  }
105|  if (na === 0 || nb === 0) return 0;
106|  return dot / (Math.sqrt(na) * Math.sqrt(nb));
107|}
