1|// Pure part of active scene tracking: from a full snapshot of every
2|// section's live top, pick the last section at or above the reading
3|// line. Falls back to the first section, so fast scrolls never blank
4|// the music. Callers re-snapshot on every observer callback and pass
5|// only the trigger.
6|export interface SceneRect {
7|  id: string;
8|  top: number;
9|}
10|
11|export function pickActiveScene(sections: SceneRect[], lineY: number): string | null {
12|  let best: string | null = null;
13|  for (const section of sections) {
14|    if (section.top <= lineY) best = section.id;
15|  }
16|  return best ?? sections[0]?.id ?? null;
17|}

