1|// Player controls: next track, mix toggle, style select. No audio here,
2|// so the bar layout can change without touching the audio engine.
3|import type { StyleInfo } from "@/core/music";
4|
5|export function PlayerControls({
6|  canNext,
7|  onNext,
8|  mixOn,
9|  onToggleMix,
10|  styles,
11|  styleId,
12|  onStyleChange,
13|}: {
14|  canNext: boolean;
15|  onNext: () => void;
16|  mixOn: boolean;
17|  onToggleMix: () => void;
18|  styles: StyleInfo[];
19|  styleId: string | null;
20|  onStyleChange: (style: string) => void;
21|}) {
22|  return (
23|    <>
24|      <button type="button" onClick={onNext} disabled={!canNext} aria-label="Cambiar track">
25|        Cambiar track
26|      </button>
27|      <button type="button" onClick={onToggleMix} aria-pressed={mixOn} aria-label="Mezclar bandas">
28|        Mezclar bandas
29|      </button>
30|      {styles.length >= 2 ? (
31|        <label className="player-note">
32|          Estilo
33|          <select
34|            value={styleId ?? ""}
35|            onChange={(e) => onStyleChange(e.target.value)}
36|            aria-label="Estilo"
37|          >
38|            {styles.map((s) => (
39|              <option key={s.id} value={s.id}>
40|                {s.name}
41|              </option>
42|            ))}
43|          </select>
44|        </label>
45|      ) : null}
46|    </>
47|  );
